input.new_string:
import { describe, expect, test } from "bun:test";
import { greet, add, slugify } from "./utils";

describe("utils", () => {
  test("greet returns greeting message", () => {
    expect(greet("Alice")).toBe("Hello, Alice!");
  });

  test("add returns sum of two numbers", () => {
    expect(add(2, 3)).toBe(5);
  });
});

describe("slugify", () => {
  describe("REQ-001: lowercase conversion", () => {
    test("converts uppercase letters to lowercase", () => {
      expect(slugify("Hello")).toBe("hello");
    });

    test("converts all uppercase to lowercase", () => {
      expect(slugify("WORLD")).toBe("world");
    });

    test("converts mixed case to lowercase", () => {
      expect(slugify("MiXeD CaSe")).toBe("mixed-case");
    });
  });

  describe("REQ-002: space and underscore replacement", () => {
    test("replaces spaces with hyphens", () => {
      expect(slugify("Hello World")).toBe("hello-world");
    });

    test("replaces underscores with hyphens", () => {
      expect(slugify("foo_bar")).toBe("foo-bar");
    });

    test("replaces both spaces and underscores with hyphens", () => {
      expect(slugify("foo bar_baz")).toBe("foo-bar-baz");
    });
  });

  describe("REQ-003: invalid character removal", () => {
    test("removes punctuation characters", () => {
      expect(slugify("Hello, World!")).toBe("hello-world");
    });

    test("removes special characters", () => {
      expect(slugify("foo@bar#baz")).toBe("foobarbaz");
    });

    test("preserves numbers", () => {
      expect(slugify("test123")).toBe("test123");
    });

    test("removes special characters and preserves numbers", () => {
      expect(slugify("price: $99.99")).toBe("price-9999");
    });
  });

  describe("REQ-004: hyphen deduplication", () => {
    test("collapses multiple hyphens into single hyphen", () => {
      expect(slugify("a---b")).toBe("a-b");
    });

    test("collapses double hyphens", () => {
      expect(slugify("foo--bar")).toBe("foo-bar");
    });

    test("collapses multiple spaces into single hyphen", () => {
      expect(slugify("test  multiple   spaces")).toBe("test-multiple-spaces");
    });
  });

  describe("REQ-005: hyphen trimming", () => {
    test("removes leading and trailing whitespace hyphens", () => {
      expect(slugify("  Hello  ")).toBe("hello");
    });

    test("removes leading and trailing hyphens", () => {
      expect(slugify("---test---")).toBe("test");
    });

    test("removes leading special characters that become hyphens", () => {
      expect(slugify("!@#foo")).toBe("foo");
    });

    test("removes trailing special characters that become hyphens", () => {
      expect(slugify("bar$%^")).toBe("bar");
    });
  });

  describe("edge cases", () => {
    test("handles empty string", () => {
      expect(slugify("")).toBe("");
    });

    test("handles all special characters", () => {
      expect(slugify("!!!")).toBe("");
    });

    test("handles combined transformation scenario", () => {
      expect(slugify("  a---b  ")).toBe("a-b");
    });
  });

  describe("example transformations", () => {
    test('transforms "Hello, World!" to "hello-world"', () => {
      expect(slugify("Hello, World!")).toBe("hello-world");
    });

    test('transforms "Foo__Bar" to "foo-bar"', () => {
      expect(slugify("Foo__Bar")).toBe("foo-bar");
    });

    test('transforms "  a---b  " to "a-b"', () => {
      expect(slugify("  a---b  ")).toBe("a-b");
    });
  });
});

